const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error('job_id must be a valid UUID');
}

return [{ json: { job_id: jobId } }];

parameters.query:
WITH i AS (SELECT $1::uuid AS job_id), j AS (
 SELECT p.* FROM public.jobs p,i WHERE p.id=i.job_id
), scenes AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
   'scene_id',s.id,'scene_number',s.scene_number,'narration',s.narration,'narration_support_evidence_ids',s.narration_support_evidence_ids,
   'beat_start_seconds',s.beat_start_seconds,'beat_end_seconds',s.beat_end_seconds,'duration_seconds',s.duration_seconds,'status',s.status
 ) ORDER BY s.scene_number),'[]'::jsonb) AS rows FROM public.scenes s,i WHERE s.job_id=i.job_id
), visual_state AS (
 SELECT (SELECT count(*)::int FROM public.visual_segments vs,i WHERE vs.job_id=i.job_id) AS segment_count,
        (SELECT count(*)::int FROM public.visual_shots sh,i WHERE sh.job_id=i.job_id) AS shot_count
)
SELECT i.job_id AS requested_job_id,j.id AS job_id,j.topic,j.language_code,j.target_duration_seconds,j.content_model_version,j.fact_primary_title,
       j.story_package,j.voiceover_path,j.voiceover_duration_seconds,j.status,j.current_stage,j.id IS NOT NULL AS job_exists,
       scenes.rows AS scenes,visual_state.segment_count AS existing_visual_segment_count,visual_state.shot_count AS existing_visual_shot_count
FROM i LEFT JOIN j ON true CROSS JOIN scenes CROSS JOIN visual_state;
